import { ProductGallery } from "@rhs-ui/commerce/product-gallery";

const svg = (body: string) => "data:image/svg+xml;utf8," + encodeURIComponent(`<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 400 500'>${body}</svg>`);

const IMAGES = [
  { src: svg("<rect width='400' height='500' fill='#e8e4dc'/><path d='M120 120h160l30 260H90z' fill='#8b7f6a'/><path d='M150 120c0-40 100-40 100 0' fill='none' stroke='#6d6353' stroke-width='10'/>"), alt: "Linen apron, front", width: 400, height: 500 },
  { src: svg("<rect width='400' height='500' fill='#dedad2'/><path d='M140 110h120l24 280H116z' fill='#7a6f5b'/><rect x='170' y='230' width='60' height='50' rx='6' fill='#6d6353'/>"), alt: "Linen apron, pocket detail", width: 400, height: 500 },
  { src: svg("<rect width='400' height='500' fill='#d4d8cf'/><circle cx='200' cy='250' r='120' fill='#8aa38b'/><path d='M150 200h100l16 120H134z' fill='#8b7f6a'/>"), alt: "Linen apron, folded", width: 400, height: 500 },
  { src: svg("<rect width='400' height='500' fill='#1b1a25'/><path d='M120 120h160l30 260H90z' fill='#e8e4dc'/>"), alt: "Linen apron in ink", width: 400, height: 500 },
];

export default function ProductGalleryDemo() {
  return <ProductGallery images={IMAGES} className="w-full max-w-xs" />;
}
